const body = $input.first().json.body || $input.first().json;
if (!body.file_url) {
  throw new Error('请求必须包含 file_url');
}
return [{ json: {
  fileUrl: String(body.file_url),
  sourceName: String(body.source_name || body.file_url.split('/').pop() || '未命名文档')
} }];

const response = $input.first().json;
const text = response.choices?.[0]?.message?.content ?? response.text ?? response.data?.text ?? response.result?.text ?? response.data?.result?.text ?? '';
if (!text || String(text).trim().length < 5) {
  throw new Error('DeepSeek 未返回可用文字，请检查图片地址是否可访问');
}
return [{ json: {
  fileUrl: $('校验文档请求').first().json.fileUrl,
  sourceName: $('校验文档请求').first().json.sourceName,
  ocrText: String(text).slice(0, 30000)
} }];

const response = $input.first().json;
let content = response.choices?.[0]?.message?.content ?? response.output_text ?? response.text ?? '';
content = String(content).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
let data;
try {
  data = JSON.parse(content);
} catch (error) {
  throw new Error(`模型结果不是合法 JSON：${content.slice(0, 300)}`);
}
const source = $('整理 OCR 结果').first().json;
return [{ json: {
  fileUrl: source.fileUrl,
  sourceName: source.sourceName,
  documentType: data.document_type || '',
  title: data.title || source.sourceName,
  documentNo: data.document_no || '',
  counterparty: data.counterparty || '',
  amount: data.amount || '',
  date: data.date || '',
  summary: data.summary || '',
  riskNote: data.risk_note || '',
  processedAt: new Date().toISOString()
} }];

